import type { ReactNode, SVGProps } from 'react'

/**
 * Icons for the WeChat-style chrome.
 *
 * Where WeChat ships the glyph, the SVG is taken verbatim from the payloads
 * embedded in `Weixin.dll` (see `WechatIcons.tsx`, generated by
 * `.cache/wxsvg/gen_icons.py`). Everything else in this file is hand-drawn to
 * match the measured client: the two-tone rail "chats" tab (coloured artwork,
 * which the monochrome payload set does not carry), the composer "voice input"
 * circle, and the empty-pane watermark logo.
 *
 * `MomentsTabIcon` uses the compass from WeChat's own design-system SVG set
 * (`.cache/wxres/tabBar_icons_outlined_discover.svg`) rather than the DLL
 * payloads, where it does not appear.
 */

type IconProps = SVGProps<SVGSVGElement> & { size?: number }

export {
  CallBubbleIcon,
  CallIcon,
  ChevronDownIcon,
  ContactsTabIcon,
  CubeTabIcon,
  DeviceIcon,
  EmojiIcon,
  FolderIcon,
  MenuIcon,
  MicIcon,
  MoreIcon,
  PlusIcon,
  ScissorsIcon,
  SearchIcon,
  StickerCubeIcon,
} from './WechatIcons'

import { CallBubbleIcon } from './WechatIcons'

/** Stroke-based helper for the hand-drawn icons below. */
function Svg({ size = 24, children, ...rest }: IconProps & { children: ReactNode }) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.7}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...rest}
    >
      {children}
    </svg>
  )
}

/** Header "voice / video call" entry: WeChat's own bubble glyph. */
export function CallMenuIcon(props: IconProps) {
  return <CallBubbleIcon {...props} />
}

/**
 * Composer "voice input" button: a ring around a microphone, with a soft sound
 * arc on the right and a dot on the left, as measured off the client.
 */
export function MicWaveIcon({ size = 24, ...rest }: IconProps) {
  return (
    <Svg size={size} strokeWidth={1.5} {...rest}>
      <circle cx="12" cy="12" r="8.6" />
      <rect x="11.85" y="7.7" width="2.7" height="8.6" rx="1.35" fill="currentColor" stroke="none" />
      <path d="M16.5 9.8a4.7 4.7 0 0 1 0 4.4" />
      <circle cx="8.8" cy="12" r="1.1" fill="currentColor" stroke="none" />
    </Svg>
  )
}

/** Side rail: 聊天 — red bubble with "…" over a green bubble. */
export function ChatsTabIcon({ size = 26, ...rest }: IconProps) {
  return (
    <svg width={size} height={size} viewBox="0 0 28 28" aria-hidden="true" {...rest}>
      <path
        d="M11.4 12.4c-5 0-9 3.2-9 7.2 0 2.3 1.3 4.3 3.3 5.6l-.9 2.8 3.4-1.6c1 .3 2.1.5 3.2.5 5 0 9-3.2 9-7.3s-4-7.2-9-7.2Z"
        fill="#07c160"
      />
      <path
        d="M17.6 3.6c-4.6 0-8.3 2.8-8.3 6.3 0 1.1.4 2.2 1.1 3.1.9-.2 1.8-.4 2.8-.4 3.3 0 6.2 1.3 7.7 3.3 3-1 5-3.4 5-6.1 0-3.5-3.7-6.2-8.3-6.2Z"
        fill="#fa5151"
      />
      <circle cx="14.4" cy="9.9" r="1.1" fill="#fff" />
      <circle cx="17.6" cy="9.9" r="1.1" fill="#fff" />
      <circle cx="20.8" cy="9.9" r="1.1" fill="#fff" />
    </svg>
  )
}

/**
 * Side rail: 发现/朋友圈 — WeChat's compass. The geometry is the design-system
 * SVG (ring plus a rhombus needle), not a redraw, so the needle angle and the
 * ring weight match the client.
 */
export function MomentsTabIcon({ size = 24, ...rest }: IconProps) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" {...rest}>
      <path d="M12,20.8 C16.8601058,20.8 20.8,16.8601058 20.8,12 C20.8,7.1398942 16.8601058,3.2 12,3.2 C7.1398942,3.2 3.2,7.1398942 3.2,12 C3.2,16.8601058 7.1398942,20.8 12,20.8 Z M12,22 C6.4771525,22 2,17.5228475 2,12 C2,6.47771525 6.4771525,2 12,2 C17.5228475,2 22,6.47771525 22,12 C22,17.5228475 17.5228475,22 12,22 Z M11.1233556,11.1233556 L9.26736162,14.7326384 L12.8766444,12.8766444 L14.7326384,9.26736162 L11.1233556,11.1233556 Z M10.232233,10.232233 L16.1243501,7.20234187 C16.2678549,7.12854767 16.4381526,7.12854767 16.5816575,7.20234187 C16.8272333,7.32862381 16.9239401,7.63007409 16.7976581,7.87564991 L13.767767,13.767767 L7.87564991,16.7976581 C7.73214506,16.8714523 7.56184738,16.8714523 7.41834253,16.7976581 C7.17276672,16.6713762 7.07605992,16.3699259 7.20234187,16.1243501 L10.232233,10.232233 Z" />
    </svg>
  )
}

/**
 * Empty-chat watermark: two overlapping WeChat bubbles, drawn with even-odd
 * holes for the eyes so it reads as the logo at low contrast. The payload set
 * has no logo, so this one stays a redraw.
 */
export function WechatWatermark({ size = 112, ...rest }: IconProps) {
  return (
    <svg width={size} height={size * 0.86} viewBox="0 0 132 114" aria-hidden="true" {...rest}>
      <path
        fillRule="evenodd"
        fill="currentColor"
        d="M40.5 6C18.1 6 0 21.2 0 40c0 10.4 5.9 19.7 15.2 25.9l-3.5 12.3 13-7.2c3.6 1 7.4 1.6 11.3 1.7C52 66 64 56.2 67.5 43.5 70.6 28.6 58.7 6 40.5 6Zm-12.8 17a4.2 4.2 0 1 0 0 8.4 4.2 4.2 0 0 0 0-8.4Zm24.6 0a4.2 4.2 0 1 0 0 8.4 4.2 4.2 0 0 0 0-8.4Z"
      />
      <path
        fillRule="evenodd"
        fill="currentColor"
        d="M95.8 38.4c-20 0-36.2 12.6-36.2 28.1 0 8.7 5.1 16.5 13.2 21.7l-2.9 10.1 11-6c3.1.8 6.4 1.2 9.8 1 19.7-.4 35.3-12.9 35.3-28.2 0-15.5-16.2-28.1-36.2-28.1Zm-9.9 14.3a3.6 3.6 0 1 0 0 7.2 3.6 3.6 0 0 0 0-7.2Zm19.8 0a3.6 3.6 0 1 0 0 7.2 3.6 3.6 0 0 0 0-7.2Z"
      />
    </svg>
  )
}
